package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class KeyedObjects2D_removeObject_TriageGen0Test {

    private KeyedObjects2D dataset;

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }

    @Test
    public void testRemoveObject_RowNotRemoved_ColumnNotRemoved() {
        // Setup: 2x2 matrix
        // (R1, C1) = Obj1, (R1, C2) = Obj2
        // (R2, C1) = Obj3, (R2, C2) = Obj4
        dataset.addObject("R1", "C1", "Obj1");
        dataset.addObject("R1", "C2", "Obj2");
        dataset.addObject("R2", "C1", "Obj3");
        dataset.addObject("R2", "C2", "Obj4");

        // Remove (R1, C1)
        dataset.removeObject("R1", "C1");

        // Verify object is null
        assertNull("Object at R1, C1 should be null", dataset.getObject("R1", "C1"));

        // Verify Row R1 is NOT removed (because R1, C2 still exists)
        assertEquals("Row count should still be 2", 2, dataset.getRowCount());
        assertEquals("R1", dataset.getRowKey(dataset.getRowIndex("R1")));

        // Verify Column C1 is NOT removed (because R2, C1 still exists)
        assertEquals("Column count should still be 2", 2, dataset.getColumnCount());
        assertEquals("C1", dataset.getColumnKey(dataset.getColumnIndex("C1")));
    }








}

