import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class KeyedObjects2D_removeObject_TriageGen0Test {

    private KeyedObjects2D dataset;

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }



    @Test
    public void testRemoveObject_RowRemoved_ColumnNotRemoved() {
        // Setup: Only one row
        // (R1, C1) = Obj1, (R1, C2) = Obj2
        dataset.addObject("R1", "C1", "Obj1");
        dataset.addObject("R1", "C2", "Obj2");

        // Remove (R1, C1) -> Row R1 still has C2, so Row is not removed
        dataset.removeObject("R1", "C1");
        assertEquals(1, dataset.getRowCount());

        // Remove (R1, C2) -> Row R1 is now empty
        dataset.removeObject("R1", "C2");

        // Verify Row R1 is removed
        assertEquals("Row count should be 0", 0, dataset.getRowCount());
        assertFalse("R1 should not be in row keys", dataset.getRowKeys().contains("R1"));

        // Verify Column C1 and C2 still exist in keys (because they weren't "allNull" in the column check phase 
        // relative to other rows, but here there are no other rows left, so let's verify logic)
        // Actually, if row count becomes 0, the column check loop runs 0 times, allNull stays true.
        // If allNull is true, columnKeys.remove(columnKey) is called.
        // However, the column check loop iterates through rows. If rows is empty, allNull stays true.
        // So the column key should be removed.

        // Let's re-verify with a scenario where one column is emptied but others remain.
    }






}

package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class KeyedObjects2D_removeObject_TriageGen0Test {

    private KeyedObjects2D dataset;

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }





    @Test
    public void testRemoveObject_ColumnRemoved() {
        // Setup: 2 rows, 1 column
        // (R1, C1) = Obj1
        // (R2, C1) = Obj2
        dataset.addObject("R1", "C1", "Obj1");
        dataset.addObject("R2", "C1", "Obj2");

        // Remove (R1, C1). Row R1 is now empty.
        dataset.removeObject("R1", "C1");

        // Row R1 should be gone. Row count = 1.
        assertEquals(1, dataset.getRowCount());
        assertEquals("R2", dataset.getRowKey(0));

        // Remove (R2, C1). Row R2 is now empty.
        dataset.removeObject("R2", "C1");

        // Row R2 should be gone. Row count = 0.
        assertEquals(0, dataset.getRowCount());

        // Since all rows are gone, the column check loop sees 0 rows, allNull remains true.
        // Therefore, column C1 should be removed.
        assertEquals(0, dataset.getColumnCount());
    }




}

