package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class KeyedObjects2D_removeObject_TriageGen0Test {

    private KeyedObjects2D dataset;

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }









    @Test
    public void testRemoveObject_ComplexScenario() {
        // Setup
        // R1: C1=V1, C2=V2
        // R2: C1=V3, C2=V4
        dataset.addObject("R1", "C1", "V1");
        dataset.addObject("R1", "C2", "V2");
        dataset.addObject("R2", "C1", "V3");
        dataset.addObject("R2", "C2", "V4");

        // Remove R1, C1.
        // R1 is NOT empty (has C2).
        // C1 is NOT empty (has R2, C1).
        dataset.removeObject("R1", "C1");
        assertEquals(2, dataset.getRowCount());
        assertEquals(2, dataset.getColumnCount());
        assertNull(dataset.getObject("R1", "C1"));

        // Remove R1, C2.
        // R1 is now empty. R1 should be removed.
        // C2 is NOT empty (has R2, C2).
        dataset.removeObject("R1", "C2");
        assertEquals(1, dataset.getRowCount());
        assertEquals("R2", dataset.getRowKey(0));
        assertEquals(2, dataset.getColumnCount());

        // Remove R2, C2.
        // R2 is now empty. R2 should be removed.
        // C2 is now empty (no more rows). C2 should be removed.
        dataset.removeObject("R2", "C2");
        assertEquals(0, dataset.getRowCount());
        assertEquals(0, dataset.getColumnCount());
    }
}
